<?php $pageTitle='Profile'; require 'config.php'; require 'includes/functions.php'; require_role('recruiter'); $uid=user()['id'];
if($_SERVER['REQUEST_METHOD']==='POST'){ $stmt=$pdo->prepare('UPDATE users SET bio=?,college=?,branch=?,graduation_year=?,location=?,company_name=?,company_description=? WHERE id=?');$stmt->execute([trim($_POST['bio']??''),trim($_POST['college']??''),trim($_POST['branch']??''),($_POST['graduation_year']??'')?:null,trim($_POST['location']??''),trim($_POST['company_name']??''),trim($_POST['company_description']??''),$uid]);flash('success','Profile updated.');header('Location: profile.php');exit;}
$stmt=$pdo->prepare('SELECT * FROM users WHERE id=?');$stmt->execute([$uid]);$u=$stmt->fetch(); include 'includes/header.php'; ?>
<div class="grid two"><div class="card"><div class="kicker">Public profile</div><h1><?=e($u['name'])?></h1><span class="badge"><?=e($u['role'])?></span><p><?=e($u['bio']?:'Add a professional bio.')?></p><p class="muted"><?=e($u['email'])?> • <?=e($u['location']?:'Location not set')?></p><h3>Trust Score: <?=e($u['trust_score'])?></h3><p class="muted">Verification: <?=e($u['verification_status'])?></p></div><div class="card"><h2>Edit Profile</h2><form method="post"><div class="form-group"><label>Bio</label><textarea name="bio"><?=e($u['bio'])?></textarea></div><div class="form-group"><label>Location</label><input name="location" value="<?=e($u['location'])?>"></div><?php if(in_array($u['role'],['student','team_leader'])):?><div class="form-group"><label>College</label><input name="college" value="<?=e($u['college'])?>"></div><div class="form-group"><label>Branch</label><input name="branch" value="<?=e($u['branch'])?>"></div><div class="form-group"><label>Graduation Year</label><input type="number" name="graduation_year" value="<?=e($u['graduation_year'])?>"></div><?php endif;?><?php if($u['role']==='recruiter'):?><div class="form-group"><label>Company Name</label><input name="company_name" value="<?=e($u['company_name'])?>"></div><div class="form-group"><label>Company Description</label><textarea name="company_description"><?=e($u['company_description'])?></textarea></div><?php endif;?><button class="btn">Save Profile</button></form></div></div>
<?php include 'includes/footer.php'; ?>
